// Package ui holds ROM Relay's templates and built front-end assets, embedded
// into the binary.
//
// dist/ is generated by `npm run build` and committed. That keeps Node out of
// `go build`, `go test`, and the container image: what ships is static CSS and
// JS. The cost of committing build output is that it can go stale, which
// ManifestMismatch exists to catch.
package ui

import (
	"crypto/sha256"
	"embed"
	"encoding/hex"
	"fmt"
	"io/fs"
	"sort"
	"strings"
)

//go:embed templates
var templatesFS embed.FS

// all: is required because go:embed skips dotfiles by default, and .manifest is
// the file the staleness check reads.
//
//go:embed all:dist
var distFS embed.FS

// Templates returns the page templates.
func Templates() fs.FS { return templatesFS }

// Assets returns the built CSS and JS, to be served under /assets/.
func Assets() fs.FS {
	sub, err := fs.Sub(distFS, "dist")
	if err != nil {
		panic("ui: dist is missing from the binary: " + err.Error())
	}
	return sub
}

//go:embed src
var sourceFS embed.FS

// ManifestMismatch reports source files whose contents no longer match the hash
// recorded when dist/ was last built. A non-empty result means someone edited
// src/ without running `npm run build`, so the committed assets, and therefore
// the binary, are stale.
//
// The comparison is a plain sha256 of embedded bytes, so this needs no Node and
// runs wherever the Go tests run.
func ManifestMismatch() ([]string, error) {
	recorded, err := distFS.ReadFile("dist/.manifest")
	if err != nil {
		return nil, fmt.Errorf("read manifest: %w", err)
	}
	want := map[string]string{}
	for _, line := range strings.Split(strings.TrimSpace(string(recorded)), "\n") {
		hash, name, found := strings.Cut(strings.TrimSpace(line), "  ")
		if !found {
			continue
		}
		want[name] = hash
	}

	var problems []string
	seen := map[string]bool{}
	// Templates are checked alongside src/: Tailwind builds its utilities by
	// scanning them, so adding a class to a template without rebuilding leaves the
	// class undefined and the page subtly wrong, which is exactly how a
	// misaligned card slipped through once.
	check := func(source fs.FS, root string) error {
		return fs.WalkDir(source, root, func(path string, entry fs.DirEntry, err error) error {
			if err != nil || entry.IsDir() {
				return err
			}
			name := path
			seen[name] = true
			data, err := fs.ReadFile(source, path)
			if err != nil {
				return err
			}
			sum := sha256.Sum256(data)
			switch recordedHash, ok := want[name]; {
			case !ok:
				problems = append(problems, name+" is not in dist/.manifest")
			case recordedHash != hex.EncodeToString(sum[:]):
				problems = append(problems, name+" changed since dist/ was built")
			}
			return nil
		})
	}
	if err := check(sourceFS, "src"); err != nil {
		return nil, err
	}
	if err := check(templatesFS, "templates"); err != nil {
		return nil, err
	}
	for name := range want {
		if !seen[name] {
			problems = append(problems, name+" is recorded in dist/.manifest but no longer exists")
		}
	}
	sort.Strings(problems)
	return problems, nil
}
